<template><main class="wrap"><h2>注文内容の確認</h2><el-skeleton v-if="loading" :rows="8" animated /><template v-else><el-table :data="items"><el-table-column prop="productName" label="商品名"/><el-table-column label="単価" width="140"><template #default="{row}">¥{{ money(row.priceAtAdd) }}</template></el-table-column><el-table-column prop="quantity" label="数量" width="100"/><el-table-column label="小計" width="140"><template #default="{row}">¥{{ money(row.priceAtAdd*row.quantity) }}</template></el-table-column></el-table><p class="total">合計金額：<strong>¥{{ money(total) }}</strong></p><el-card><template #header>配送先情報</template><el-form :model="form" label-width="120px"><el-form-item label="受取人氏名"><el-input v-model="form.receiverName" /></el-form-item><el-form-item label="電話番号"><el-input v-model="form.receiverPhone" /></el-form-item><el-form-item label="配送先住所"><el-input v-model="form.shippingAddress" type="textarea" :rows="3" /></el-form-item></el-form><div class="actions"><el-button @click="router.push('/cart')">戻る</el-button><el-button type="primary" :loading="submitting" @click="submit">注文を確定する</el-button></div></el-card></template></main></template>
<script setup>
import { computed,onMounted,ref } from 'vue';import { ElMessage } from 'element-plus';import { useRouter } from 'vue-router';import { getCart } from '@/api/cart';import { createOrder } from '@/api/order'
const router=useRouter(),loading=ref(false),submitting=ref(false),items=ref([]),form=ref({receiverName:'',receiverPhone:'',shippingAddress:''}),total=computed(()=>items.value.reduce((s,i)=>s+Number(i.priceAtAdd)*i.quantity,0)),money=(v)=>Number(v).toFixed(2)
const fetch=async()=>{loading.value=true;try{items.value=((await getCart()).data.items)||[];if(!items.value.length){ElMessage.warning('カートが空です');router.replace('/cart')}}catch(e){ElMessage.error('カート情報の取得に失敗しました')}finally{loading.value=false}}
const submit=async()=>{if(Object.values(form.value).some(v=>!v.trim()))return ElMessage.warning('配送先情報をすべて入力してください');submitting.value=true;try{const {data}=await createOrder(form.value);ElMessage.success('注文を作成しました');router.replace(`/orders/${data.id}`)}catch(e){ElMessage.error(e.response?.data?.message||'注文に失敗しました')}finally{submitting.value=false}};onMounted(fetch)
</script><style scoped>.wrap{max-width:900px;margin:auto;padding:24px}.total{text-align:right;font-size:20px}.total strong{color:#f56c6c}.actions{display:flex;justify-content:flex-end;gap:12px}</style>
